#include <iostream>
#include <string>

int main() {
    std::string user_input;
    std::getline(std::cin, user_input);
    std::string inner_str = user_input.substr(1, user_input.size() - 2);
    size_t length_inner = inner_str.length();
    std::string result_str(1, user_input[0]);
    size_t counter = 0;
    bool found_at_symbol = false;

    while (counter < length_inner) {
        if (counter + 3 <= length_inner) {
            if (inner_str.substr(counter, 3) == "dot") {
                result_str += ".";
                counter += 3;
                continue;
            }
        }
        if (counter + 2 <= length_inner && !found_at_symbol) {
            if (inner_str.substr(counter, 2) == "at") {
                result_str += "@";
                found_at_symbol = true;
                counter += 2;
                continue;
            }
        }
        result_str += inner_str[counter];
        ++counter;
    }
    result_str += user_input.back();
    std::cout << result_str << std::endl;
    return 0;
}
